#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto apply_op=[&](int x,int y){
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
        ops.push_back({x,y});
    };
    for(int i=0;i<n-1;i++){
        int j=-1;
        for(int k=i;k<n;k++) if(p[k]==i+1){j=k;break;}
        if(j==i) continue;
        // Move element from position j to position i
        // Step 1: move it to position 0 using op(j, 1) if j>=1 and j+1<=n-1
        if(j>0 && j<n-1){
            apply_op(j,1);
            // now target was at position j, after op: it's at position n-1 - ... 
            // Actually: new = [p[n-1], p[j..n-2], p[0..j-1]]
            // target was p[j], now at position 1... wait no
            // new[0]=p[n-1], new[1]=p[j], ..., so target is at position 1
            // Then op(1, n-1-i) to place it at position i
            if(1+n-1-i<=n-1) apply_op(1, n-1-i);
            else{ apply_op(1,1); i--; } // retry
        } else if(j==n-1){
            // target at last position, use op(1, n-1-i)
            if(n-i<=n-1) apply_op(1, n-1-i);
            else{ apply_op(1,1); i--; }
        } else {
            // j==0 shouldn't happen since j>=i and if j==i we skipped
            apply_op(1,1); i--;
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
